    NgramPlacement ngram_placement;
    // KV cache data type (`--kv-cache-dtype`).
    KvCacheDtype kv_cache_dtype;
    // Speculative tokens per step (`--num-speculative-tokens`).
    int64_t num_speculative_tokens;
    // RoPE scaling specification (`--rope-scaling`).
    std::string rope_scaling;
    // Prefix resume policy (`--prefix-resume`).
    PrefixResume prefix_resume;
    // Cross-rank all-reduce payload (`--tp-wire`; amendment 11): `exact`, or `wht6`, a lossy 6-bit transform.
    std::optional<TpWire> tp_wire;
    // Present means prefix caching is disabled (`--no-prefix-cache`; amendment 11). Not the host KV tier size
